function kbcc_chat_mode_page(){if(!current_user_can('manage_options'))return;$mode=kbcc_chat_mode();?><div class="wrap"><h1>KB Movies Chat Mode</h1><?php if(isset($_GET['updated'])):?><div class="notice notice-success is-dismissible"><p>Chat mode updated.</p></div><?php endif;?><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><?php wp_nonce_field('kbcc_save_chat_mode');?><input type="hidden" name="action" value="kbcc_save_chat_mode"><fieldset style="max-width:760px;background:#fff;border:1px solid #dcdcde;border-radius:10px;padding:18px"><legend class="screen-reader-text">Choose chat mode</legend><label style="display:block;margin-bottom:14px"><input type="radio" name="mode" value="whatsapp" <?php checked($mode,'whatsapp');?>> <strong>WhatsApp customer-care selector</strong><br><span class="description" style="margin-left:25px">Show the previous WhatsApp floating button and let users choose an available customer-care contact.</span></label><label style="display:block"><input type="radio" name="mode" value="native" <?php checked($mode,'native');?>> <strong>Native in-app customer care</strong><br><span class="description" style="margin-left:25px">Show the new full-screen native chat system.</span></label></fieldset><?php submit_button('Save Chat Mode');?></form><p><a href="<?php echo esc_url(admin_url('themes.php?page=kb-movies-theme-settings'));?>">Manage WhatsApp customer-care names, numbers, pictures and availability</a></p></div><?php }
add_action('admin_post_kbcc_save_chat_mode',function(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('kbcc_save_chat_mode');update_option('kbcc_chat_mode',sanitize_key($_POST['mode']??'')==='native'?'native':'whatsapp',false);wp_safe_redirect(add_query_arg('updated','1',admin_url('options-general.php?page=kbcc-chat-mode')));exit;});
add_action('admin_menu',function(){add_options_page('KB Notification Test','KB Notification Test','manage_options','kbcc-notification-test','kbcc_notification_test_page');});
function kbcc_notification_test_page(){if(!current_user_can('manage_options'))return;global $wpdb;[,, $d]=kbcc_tables();$settings=(array)get_option('kbcc_fcm',[]);$agents=get_users(['role__in'=>['kbcc_agent','administrator']]);$counts=$wpdb->get_results("SELECT user_id,COUNT(*) total,MAX(updated_at) last_seen FROM $d GROUP BY user_id",OBJECT_K);$error=get_option('kbcc_last_push_error','');?><div class="wrap"><h1>KB Customer-Care Notification Test</h1><table class="widefat striped" style="max-width:850px"><tbody><tr><th>Firebase project</th><td><?php echo !empty($settings['project_id'])?esc_html($settings['project_id']):'<strong style="color:#b32d2e">Missing</strong>';?></td></tr><tr><th>Service-account email</th><td><?php echo !empty($settings['client_email'])?esc_html($settings['client_email']):'<strong style="color:#b32d2e">Missing</strong>';?></td></tr><tr><th>Private key</th><td><?php echo !empty($settings['private_key'])?'<strong style="color:#087147">Saved</strong>':'<strong style="color:#b32d2e">Missing</strong>';?></td></tr><tr><th>Last Firebase result</th><td><?php echo $error?'<strong style="color:#b32d2e">'.esc_html($error).'</strong>':'<strong style="color:#087147">No delivery error recorded</strong>';?></td></tr></tbody></table><h2>Registered customer-care devices</h2><table class="widefat striped" style="max-width:850px"><thead><tr><th>Customer care</th><th>Devices</th><th>Last registered</th></tr></thead><tbody><?php foreach($agents as $agent):$row=$counts[$agent->ID]??null;?><tr><td><?php echo esc_html($agent->display_name);?></td><td><?php echo $row?absint($row->total):'<strong style="color:#b32d2e">0 — sign in to the updated app</strong>';?></td><td><?php echo $row?esc_html($row->last_seen):'—';?></td></tr><?php endforeach;?></tbody></table><h2>Send a test notification</h2><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><?php wp_nonce_field('kbcc_test_push');?><input type="hidden" name="action" value="kbcc_test_push"><select name="agent_id" required><option value="">Select customer care</option><?php foreach($agents as $agent):?><option value="<?php echo absint($agent->ID);?>"><?php echo esc_html($agent->display_name);?></option><?php endforeach;?></select><?php submit_button('Send Test Notification','primary','submit',false);?></form><p><a href="<?php echo esc_url(admin_url('options-general.php?page=kbcc'));?>">Open Firebase credential settings</a></p></div><?php }
add_action('admin_post_kbcc_test_push',function(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('kbcc_test_push');delete_option('kbcc_last_push_error');kbcc_push_agent(absint($_POST['agent_id']??0),'KB Movies Test','Firebase notification test successful.',0);wp_safe_redirect(admin_url('options-general.php?page=kbcc-notification-test'));exit;});
add_action('wp',function(){if(kbcc_chat_mode()!=='whatsapp')return;if(function_exists('mk_movies_whatsapp_team_assets')&&!has_action('wp_enqueue_scripts','mk_movies_whatsapp_team_assets'))add_action('wp_enqueue_scripts','mk_movies_whatsapp_team_assets',40);if(function_exists('mk_movies_whatsapp_team_float')&&!has_action('wp_footer','mk_movies_whatsapp_team_float'))add_action('wp_footer','mk_movies_whatsapp_team_float',30);},20);
